export const resolveImageUrl = (path: string | null | undefined): string => {
    if (!path) return 'https://via.placeholder.com/300';
    if (path.startsWith('http')) return path;
    
    const baseUrl = 'https://menhaapi.smartseyali.app';
    let cleanPath = path;

    // Remove leading slash for consistency in checking
    if (cleanPath.startsWith('/')) cleanPath = cleanPath.substring(1);

    // If path already starts with assets, just join
    if (cleanPath.startsWith('assets/')) {
        return `${baseUrl}/${cleanPath}`;
    }

    // If path looks like a filename (no slashes), assume it's a product image
    if (!cleanPath.includes('/')) {
        // Warning: The backend seems to expect the filename to be part of the path, 
        // but some filenames might contain spaces or special chars that need encoding only once.
        // If the path comes from DB, it might be raw.
        // We will encode components to be safe for URL.
        const encodedFilename = encodeURIComponent(cleanPath).replace(/%20/g, '+'); 
        // However, looking at the user Screenshot, the URL is:
        // .../assets/img/product/malt-1-1768805466537-943460037.png
        // Which works. But the one failing is .../assets/img/product/malt%201-1768805466537-943460037.png (with %20)
        // If the file on disk has spaces, the backend expects the URL to have encoded spaces.
        // But if we send it as is, React Native Image component might encode it automatically?
        // Let's rely on standard encoding.
        return `${baseUrl}/assets/img/product/${cleanPath}`;
    }

    // Fallback for other paths
    return `${baseUrl}/${cleanPath}`;
};
